      background-color: #f2f2f7;
      color: var(--color-text);
      line-height: 1.5;
      -webkit-font-smoothing: antialiased;
    }
    /* Arabic type rules */
    :lang(ar) {
      --type-label-size: 14px;
      --type-body-size: 16px;
      letter-spacing: 0;
      text-transform: none;
      font-style: normal;
      line-height: 1.7;
    }
    .container {
      max-width: 375px;
      margin: 0 auto;
      background: #fff;
      min-height: 100vh;
      box-shadow: 0 0 10px rgba(0,0,0,0.05);
