      padding: 1rem;
      border-bottom: 1px solid var(--color-border);
      display: flex;
      align-items: center;
      justify-content: flex-start;
    }
    header h1 {
      font-size: 1.125rem;
      font-weight: 600;
    }
    /* Groups */
    .group {
      margin-top: 1.5rem;
    }
    .group-title {
      font-size: var(--type-label-size);
      font-weight: 600;
      color: var(--color-secondary);
      padding: 0 1rem 0.5rem 1rem;
      text-align: start;
    }
    .row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0.75rem 1rem;
      border-bottom: 1px solid var(--color-border);
      min-height: 44px;
    }
    .row-content {
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      gap: 2px;
    }
    .row-label {
      font-size: var(--type-body-size);
      font-weight: 400;
    }
    .row-value {
      font-size: var(--type-label-size);
      color: var(--color-secondary);
    }
    /* Chevron */
    .chevron {
      width: 24px;
      height: 24px;
      color: var(--color-secondary);
      flex-shrink: 0;
    }
    /* Toggle switch */
    .toggle {
      position: relative;
      width: 51px;
      height: 31px;
      flex-shrink: 0;
    }
    .toggle input {
      opacity: 0;
      width: 0;
      height: 0;
    }
    .slider {
      position: absolute;
      cursor: pointer;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background-color: #ccc;
      transition: .4s;
      border-radius: 34px;
    }
    .slider:before {
      position: absolute;
      content: "";
      height: 23px;
      width: 23px;
      left: 4px;
      bottom: 4px;
      background-color: white;
      transition: .4s;
      border-radius: 50%;
    }
    input:checked + .slider {
      background-color: var(--color-accent);
    }
    input:checked + .slider:before {
      transform: translateX(20px);
    }
    /* RTL toggle flip */
    :dir(rtl) .slider:before {
      right: 4px;
      left: auto;
    }
    :dir(rtl) input:checked + .slider:before {
      transform: translateX(-20px);
    }
    /* Isolate Latin runs */
    bdi {
      unicode-bidi: isolate;
    }
  </style>
</head>
